-- Single-specialist service desk; operational roles use the existing access catalog.
insert into private.app_modules values('it_support','دعم تقنية المعلومات','monitor-cog','it-support/index.html',true,100);
insert into private.access_catalog(key,module,label,operation,scopes,sort_order)values
('it_support.operate','دعم تقنية المعلومات','تشغيل الدعم التقني','operate',array['all'],110),
('it_support.supervise','دعم تقنية المعلومات','الإشراف على الدعم والتصعيد','supervise',array['all'],111);
create table private.it_support_settings(singleton boolean primary key default true check(singleton),specialist_id uuid references public.profiles(id),supervisor_id uuid references public.profiles(id));
insert into private.it_support_settings(singleton)values(true);
create table private.it_support_services(key text primary key,label text not null,kind text not null check(kind in('incident','service','access','change')),approval boolean not null default false);
insert into private.it_support_services values('device_fault','عطل جهاز أو طابعة','incident',false),('network_fault','عطل شبكة أو إنترنت','incident',false),('system_fault','عطل نظام أو برنامج','incident',false),('equipment','تجهيز جهاز أو برنامج','service',true),('account','إنشاء أو تعديل حساب وصلاحية','access',true),('change','تطوير أو تغيير تقني','change',true),('help','استفسار ومساعدة تقنية','service',false);
create table private.it_support_tickets(
 id uuid primary key default gen_random_uuid(),number bigint generated always as identity unique,
 requester_id uuid not null references public.profiles(id),beneficiary_id uuid not null references public.profiles(id),
 approver_id uuid references public.profiles(id),specialist_id uuid not null references public.profiles(id),supervisor_id uuid not null references public.profiles(id),
 service_key text not null references private.it_support_services(key),title text not null check(length(btrim(title))between 5 and 160),description text not null check(length(btrim(description))between 10 and 10000),
 impact int not null check(impact between 1 and 3),urgency int not null check(urgency between 1 and 3),priority int not null check(priority between 1 and 4),
 state text not null check(state in('approval','new','working','waiting_employee','waiting_vendor','resolved','closed','cancelled','rejected')),
 solution text not null default '',revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),state_since timestamptz not null default now(),resolved_at timestamptz,rating int check(rating between 1 and 5)
);
create index it_support_requester_idx on private.it_support_tickets(requester_id);
create index it_support_beneficiary_idx on private.it_support_tickets(beneficiary_id);
create index it_support_approver_idx on private.it_support_tickets(approver_id);
create index it_support_specialist_idx on private.it_support_tickets(specialist_id);
create index it_support_supervisor_idx on private.it_support_tickets(supervisor_id);
create index it_support_service_idx on private.it_support_tickets(service_key);
create index it_support_state_idx on private.it_support_tickets(state,priority,created_at);
create table private.it_support_messages(id bigint generated always as identity primary key,ticket_id uuid not null references private.it_support_tickets(id),actor_id uuid not null references public.profiles(id),body text not null check(length(btrim(body))between 2 and 10000),internal boolean not null default false,created_at timestamptz not null default now());
create index it_support_message_ticket_idx on private.it_support_messages(ticket_id,id);
create index it_support_message_actor_idx on private.it_support_messages(actor_id);
create table private.it_support_events(id bigint generated always as identity primary key,ticket_id uuid not null references private.it_support_tickets(id),actor_id uuid references public.profiles(id),action text not null,note text not null default '',created_at timestamptz not null default now());
create index it_support_event_ticket_idx on private.it_support_events(ticket_id,id);
create index it_support_event_actor_idx on private.it_support_events(actor_id);
do $$declare t text;begin foreach t in array array['it_support_settings','it_support_services','it_support_tickets','it_support_messages','it_support_events']loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);execute format('create policy internal_only on private.%I to authenticated using(false)with check(false)',t);end loop;end$$;
create function private.it_support_permission(k text)returns boolean language sql stable security definer set search_path=pg_catalog,private,public as $$select private.module_allowed('it_support')and exists(select 1 from public.profiles where id=auth.uid()and(role='admin'or k=any(permissions)))$$;
create function private.it_support_visible(ticket uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private,public as $$select private.module_allowed('it_support')and exists(select 1 from private.it_support_tickets t where t.id=ticket and(auth.uid()in(t.requester_id,t.beneficiary_id,t.approver_id)or private.it_support_permission('it_support.operate')or private.it_support_permission('it_support.supervise')))$$;
create function private.it_support_notify(ticket uuid)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare t private.it_support_tickets;u uuid;begin select * into strict t from private.it_support_tickets where id=ticket;for u in select distinct x from unnest(array[t.requester_id,t.beneficiary_id,case when t.state='approval'then t.approver_id when t.state in('new','working','waiting_vendor')then t.specialist_id end,case when t.priority=1 then t.supervisor_id end])x where x is not null and x<>auth.uid()loop insert into public.notifications(recipient_id,type,title,message)values(u,'IT_SUPPORT','تحديث طلب دعم IT-'||t.number,'يوجد تحديث على طلب دعم تقنية المعلومات.');end loop;end$$;
create function private.it_support_context()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin perform private.require_module('it_support');return jsonb_build_object('user_id',auth.uid(),'operator',private.it_support_permission('it_support.operate'),'supervisor',private.it_support_permission('it_support.supervise'),'admin',exists(select 1 from public.profiles where id=auth.uid()and role='admin'),'settings',(select to_jsonb(s)from private.it_support_settings s),'services',(select jsonb_agg(to_jsonb(s)order by key)from private.it_support_services s),'people',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'full_name',full_name,'manager_id',manager_id,'operate',role='admin'or'it_support.operate'=any(permissions),'supervise',role='admin'or'it_support.supervise'=any(permissions))order by full_name),'[]')from public.profiles where active and status='active'and(private.it_support_permission('it_support.supervise')or id=auth.uid()or manager_id=auth.uid()or id in(select specialist_id from private.it_support_settings)or id in(select supervisor_id from private.it_support_settings))));end$$;
create function private.it_support_configure(specialist uuid,supervisor uuid)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$begin
if not private.it_support_permission('it_support.supervise')then raise exception 'الإعدادات لمشرف تطوير الأعمال أو مسؤول النظام'using errcode='42501';end if;
if specialist=supervisor or not exists(select 1 from public.profiles where id=specialist and active and status='active'and(role='admin'or('it_support'=any(allowed_modules)and'it_support.operate'=any(permissions))))or not exists(select 1 from public.profiles where id=supervisor and active and status='active'and(role='admin'or('it_support'=any(allowed_modules)and'it_support.supervise'=any(permissions))))then raise exception 'حدد أخصائيًا ومشرفًا مختلفين بصلاحيات معتمدة من إدارة الحسابات';end if;
update private.it_support_settings set specialist_id=specialist,supervisor_id=supervisor where singleton;end$$;
create function private.it_support_create(p_data jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,private,public as $$declare s private.it_support_settings;v private.it_support_services;b public.profiles;a uuid;i uuid;impact int:=(p_data->>'impact')::int;urgency int:=(p_data->>'urgency')::int;begin
perform private.require_module('it_support');select * into strict s from private.it_support_settings;
if s.specialist_id is null or s.supervisor_id is null then raise exception 'لم يكتمل إعداد مسؤول الدعم ومرجعيته';end if;
if not exists(select 1 from public.profiles where id=s.specialist_id and active and status='active'and(role='admin'or('it_support'=any(allowed_modules)and'it_support.operate'=any(permissions))))then raise exception 'أخصائي الدعم غير متاح؛ راجع المشرف';end if;
select * into strict v from private.it_support_services where key=p_data->>'service_key';select * into strict b from public.profiles where id=coalesce(nullif(p_data->>'beneficiary_id','')::uuid,auth.uid())and active and status='active';
if b.id<>auth.uid()and b.manager_id is distinct from auth.uid()then raise exception 'يمكنك تقديم الطلب لنفسك أو فريقك المباشر'using errcode='42501';end if;
if v.approval then a:=case when v.kind in('access','change')then s.supervisor_id else coalesce(b.manager_id,s.supervisor_id)end;if a=auth.uid()then a:=s.supervisor_id;end if;if a=auth.uid()then raise exception 'يجب أن يعتمد الطلب شخص آخر';end if;end if;
insert into private.it_support_tickets(requester_id,beneficiary_id,approver_id,specialist_id,supervisor_id,service_key,title,description,impact,urgency,priority,state)values(auth.uid(),b.id,a,s.specialist_id,s.supervisor_id,v.key,p_data->>'title',p_data->>'description',impact,urgency,case when impact=3 and urgency=3 then 1 when impact+urgency>=5 then 2 when impact+urgency>=3 then 3 else 4 end,case when v.approval then 'approval'else 'new'end)returning id into i;
insert into private.it_support_events(ticket_id,actor_id,action)values(i,auth.uid(),'created');perform private.it_support_notify(i);return i;end$$;
create function private.it_support_list()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin perform private.require_module('it_support');return(select coalesce(jsonb_agg(to_jsonb(q)order by priority,created_at desc),'[]')from(select t.*,p.full_name beneficiary_name,o.full_name owner_name,case when t.state='approval'then t.approver_id when t.state in('waiting_employee','resolved')then t.beneficiary_id else t.specialist_id end owner_id from private.it_support_tickets t join public.profiles p on p.id=t.beneficiary_id left join public.profiles o on o.id=case when t.state='approval'then t.approver_id when t.state in('waiting_employee','resolved')then t.beneficiary_id else t.specialist_id end where private.it_support_visible(t.id)order by t.created_at desc limit 500)q);end$$;
create function private.it_support_detail(p_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin if not private.it_support_visible(p_id)then raise exception 'الطلب غير متاح'using errcode='42501';end if;return jsonb_build_object('ticket',(select to_jsonb(t)from private.it_support_tickets t where id=p_id),'messages',(select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('actor_name',p.full_name)order by m.id),'[]')from private.it_support_messages m join public.profiles p on p.id=m.actor_id where ticket_id=p_id and(not internal or private.it_support_permission('it_support.operate')or private.it_support_permission('it_support.supervise'))),'events',case when exists(select 1 from public.profiles where id=auth.uid()and role='admin')then(select coalesce(jsonb_agg(to_jsonb(e)order by id),'[]')from private.it_support_events e where ticket_id=p_id)else '[]'::jsonb end);end$$;
create function private.it_support_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare t private.it_support_tickets;n text;note text:=btrim(coalesce(p_data->>'note',''));op boolean:=private.it_support_permission('it_support.operate');begin
if not private.it_support_visible(p_id)then raise exception 'الطلب غير متاح'using errcode='42501';end if;select * into strict t from private.it_support_tickets where id=p_id for update;
if t.revision<>p_revision then raise exception 'تم تحديث الطلب؛ أعد تحميله'using errcode='40001';end if;
if length(note)<3 then raise exception 'اكتب توضيحًا لا يقل عن 3 أحرف';end if;
if p_action='comment'and t.state not in('closed','cancelled','rejected')then
if coalesce((p_data->>'internal')::boolean,false)and not(op or private.it_support_permission('it_support.supervise'))then raise exception 'الملاحظة الداخلية للدعم والإشراف فقط'using errcode='42501';end if;
insert into private.it_support_messages(ticket_id,actor_id,body,internal)values(t.id,auth.uid(),note,coalesce((p_data->>'internal')::boolean,false));n:=case when t.state='waiting_employee'and auth.uid()in(t.requester_id,t.beneficiary_id)then 'working'else t.state end;
elsif p_action in('approve','reject')and t.state='approval'and auth.uid()=t.approver_id and auth.uid()<>t.requester_id then n:=case p_action when 'approve'then 'new'else 'rejected'end;
elsif p_action in('working','waiting_employee','waiting_vendor','resolve')and op and t.state in('new','working','waiting_employee','waiting_vendor')then n:=case p_action when 'resolve'then 'resolved'else p_action end;if p_action='resolve'and length(note)<10 then raise exception 'وثق الحل بعشرة أحرف على الأقل';end if;
elsif p_action='close'and t.state='resolved'and auth.uid()in(t.requester_id,t.beneficiary_id)then n:='closed';if (p_data->>'rating')::int not between 1 and 5 or p_data->>'rating'is null then raise exception 'اختر تقييمًا من 1 إلى 5';end if;
elsif p_action='reopen'and t.state in('resolved','closed')and t.resolved_at>now()-interval '5 days'and auth.uid()in(t.requester_id,t.beneficiary_id)then n:='working';
elsif p_action='cancel'and t.state in('approval','new')and auth.uid()=t.requester_id then n:='cancelled';
else raise exception 'الإجراء غير متاح لك في المرحلة الحالية'using errcode='42501';end if;
update private.it_support_tickets set state=n,state_since=case when state<>n then now()else state_since end,solution=case when p_action='resolve'then note else solution end,resolved_at=case when p_action='resolve'then now()when p_action='reopen'then null else resolved_at end,rating=case when p_action='close'then(p_data->>'rating')::int when p_action='reopen'then null else rating end,revision=revision+1,updated_at=now()where id=t.id;
insert into private.it_support_events(ticket_id,actor_id,action,note)values(t.id,auth.uid(),p_action,note);perform private.it_support_notify(t.id);end$$;
-- Public invoker wrappers expose only the checked commands, never the underlying tables.
create function public.it_support_context()returns jsonb language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_context()$$;
create function public.it_support_configure(specialist uuid,supervisor uuid)returns void language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_configure(specialist,supervisor)$$;
create function public.it_support_create(p_data jsonb)returns uuid language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_create(p_data)$$;
create function public.it_support_list()returns jsonb language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_list()$$;
create function public.it_support_detail(p_id uuid)returns jsonb language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_detail(p_id)$$;
create function public.it_support_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language sql security invoker set search_path=pg_catalog,private as $$select private.it_support_action(p_id,p_revision,p_action,p_data)$$;
do $$declare f record;begin for f in select n.nspname,p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private')and p.proname like 'it_support_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);if f.proname in('it_support_context','it_support_configure','it_support_create','it_support_list','it_support_detail','it_support_action')then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
